import React from "react";

import "./styles/merchant-products.css"

import {
  BrowserRouter,
  Navigate,
  Route,
  Routes,
} from "react-router-dom";

import {
  AuthProvider,
  useAuth,
} from "./context/AuthContext.js";

import DashboardLayout from "./components/dashboard/DashboardLayout.js";
import ComingSoon from "./components/ComingSoon.js";
import MerchantProducts from "./pages/MerchantProducts.js";
import LandingPage from "./pages/LandingPage.js";
import Login from "./pages/Login.js";
import RegisterAccount from "./pages/RegisterAccount.js";
import RegisterStore from "./pages/RegisterStore.js";
import ForgotPassword from "./pages/ForgotPassword.js";
import ResetPassword from "./pages/ResetPassword.js";
import Dashboard from "./pages/Dashboard.js";

const ProtectedRoute = ({ children }) => {
  const {
    user,
    loading,
  } = useAuth();

  if (loading) {
    return <p>Checking authentication...</p>
  }

  if (!user) {
    return (
      <Navigate
        to="/login"
        replace
      />
    );
  }

  if (!user?.tenant) {
    return (
      <Navigate
        to="/register-store"
        replace
      />
    );
  }

  return children;
};

const StoreSetupRoute = ({ children }) => {
  const {
    user,
    loading,
  } = useAuth();

  if (loading) {
    return <p>Checking authentication...</p>;
  }

  if (!user) {
    return (
      <Navigate
        to="/login"
        replace
      />
    );
  }

  if (user.tenant) {
    return (
      <Navigate
        to="/dashboard"
        replace
      />
    );
  }

  return children;
};

const PublicRoute = ({ children }) => {
  const {
    user,
    loading,
  } = useAuth();

  if (loading) {
    return <p>Checking authentication...</p>;
  }

  if (!user) {
    return children;
  }

  if (!user.tenant) {
    return (
      <Navigate
        to="/register-store"
        replace
      />
    );
  }

  return (
    <Navigate
      to="/dashboard"
      replace
    />
  );
};

const RecoveryRoute = ({ children }) => {
  return children;
};

function AppRoutes() {
  return (
    <Routes>
      <Route
        path="/"
        element={<LandingPage />}
      />

      <Route
        path="/login"
        element={
          <PublicRoute>
            <Login />
          </PublicRoute>
        }
      />

      <Route
        path="/register-account"
        element={
          <PublicRoute>
            <RegisterAccount />
          </PublicRoute>
        }
      />

      <Route
        path="/forgot-password"
        element={
          <RecoveryRoute>
            <ForgotPassword />
          </RecoveryRoute>
        }
      />

      <Route
        path="/reset-password/:token"
        element={
          <RecoveryRoute>
            <ResetPassword />
          </RecoveryRoute>
        }
      />

      <Route
        path="/register-store"
        element={
          <StoreSetupRoute>
            <RegisterStore />
          </StoreSetupRoute>
        }
      />

      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <Dashboard />
          </ProtectedRoute>
        }
      />

      <Route
        path="/dashboard/products"
        element={
          <ProtectedRoute>
            <DashboardLayout>
              <MerchantProducts />
            </DashboardLayout>
          </ProtectedRoute>
        }
      />

      <Route
        path="/dashboard/templates"
        element={
          <ProtectedRoute>
            <ComingSoon title="Templates" />
          </ProtectedRoute>
        }
      />

      <Route
        path="/dashboard/orders"
        element={
          <ProtectedRoute>
            <ComingSoon title="Orders" />
          </ProtectedRoute>
        }
      />

      <Route
        path="/dashboard/customers"
        element={
          <ProtectedRoute>
            <ComingSoon title="Customers" />
          </ProtectedRoute>
        }
      />

      <Route
        path="/dashboard/growth"
        element={
          <ProtectedRoute>
